function Wait-Ui([int]$Milliseconds) { $frame = New-Object Windows.Threading.DispatcherFrame; $timer = New-Object Windows.Threading.DispatcherTimer; $timer.Interval = [TimeSpan]::FromMilliseconds($Milliseconds); $timer.Add_Tick({ $timer.Stop(); $frame.Continue = $false }); $timer.Start(); [Windows.Threading.Dispatcher]::PushFrame($frame) }
function Save-Shot([string]$Path) { $window.UpdateLayout(); $w=[Math]::Max(1,[int][Math]::Ceiling($window.ActualWidth));$h=[Math]::Max(1,[int][Math]::Ceiling($window.ActualHeight));$capture=[Activator]::CreateInstance([Windows.Media.Imaging.RenderTargetBitmap],[object[]]@($w,$h,96.0,96.0,[Windows.Media.PixelFormats]::Pbgra32));$capture.Render($window);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($capture));$stream=[IO.File]::Open($Path,[IO.FileMode]::Create,[IO.FileAccess]::Write);try{$encoder.Save($stream)}finally{$stream.Dispose()};"${w}x${h}" }
function Write-CirclePgm([string]$Path) { $w=640; $h=420; $header=[Text.Encoding]::ASCII.GetBytes("P5`n$w $h`n255`n"); $pixels=New-Object byte[] ($w*$h); for($r=0;$r -lt $h;$r++){for($c=0;$c -lt $w;$c++){ $d=($r-210)*($r-210)+($c-320)*($c-320); $pixels[$r*$w+$c]=if($d -le 110*110){220}else{35} }}; $bytes=New-Object byte[] ($header.Length+$pixels.Length); [Array]::Copy($header,0,$bytes,0,$header.Length); [Array]::Copy($pixels,0,$bytes,$header.Length,$pixels.Length); [IO.File]::WriteAllBytes($Path,$bytes) }
$temp = Join-Path ([IO.Path]::GetTempPath()) ('halcon-vm-s23-ui-'+[Guid]::NewGuid().ToString('N')); [IO.Directory]::CreateDirectory($temp)|Out-Null; $image=Join-Path $temp 'circle-part.pgm'; Write-CirclePgm $image
