$flow=$main.GetField('flowTools',$private).GetValue($window);$create=$main.GetMethod('CreateFlowTool',$private);$execute=$main.GetMethod('ExecuteFlowTool',$private);$dispose=$main.GetMethod('DisposeFlowTools',$private);$refresh=$main.GetMethod('RefreshUiState',$private);$manual=$main.GetMethod('EnableManualFlowLayout',$private);$open=$main.GetMethod('OpenSelectedToolConfiguration',$private);$reset=$main.GetMethod('ResetFlowEditHistory',$private);$align=$main.GetMethod('AlignFlowToolsHorizontalButton_Click',$private)
function New-Tool([string]$Kind,[string]$Name){$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,$Kind),$Name,$true,$null))};function Run-Tool($Tool){try{$execute.Invoke($window,[object[]]@($Tool,'S23 UI'))|Out-Null}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
$dispose.Invoke($window,@())|Out-Null;$flow.Clear();$source=New-Tool ImageSource 'Circle Image';$threshold=New-Tool ImageThreshold 'Circle Region';$contour=New-Tool RegionContourMeasurement 'Circle Border XLD';$fit=New-Tool XldCircleFitting 'Tukey Circle Fit';$judge=New-Tool NumericJudge 'Radius Judge'
$source.Parameters.LocalImagePath=$image;$source.Parameters.LocalImageSerialNumber='S23-CIRCLE-001';$threshold.Parameters.ImageThresholdMinGray=150;$threshold.Parameters.ImageThresholdMaxGray=255;$fit.Parameters.XldCircleFitAlgorithm='ATukey';$fit.Parameters.XldCircleFitMaxClosureDistance=1.5;$judge.NumericOperator='BetweenInclusive';$judge.NumericLowerLimit=105;$judge.NumericUpperLimit=115
foreach($tool in @($source,$threshold,$contour,$fit,$judge)){$flow.Add($tool)};$threshold.SetInputBinding('Image',$source.ToolId,'Image');$contour.SetInputBinding('Region',$threshold.ToolId,'Region');$fit.SetInputBinding('XLD',$contour.ToolId,'XLD');$judge.SetInputBinding('Value',$fit.ToolId,'Radius');$judge.InputToolId=$fit.ToolId;$judge.InputPortName='Radius';foreach($tool in @($source,$threshold,$contour,$fit,$judge)){Run-Tool $tool}
$window.WindowStartupLocation=[Windows.WindowStartupLocation]::Manual;$window.WindowState=[Windows.WindowState]::Normal;$window.Left=2;$window.Top=2;$window.Width=1680;$window.Height=1110;$window.Topmost=$true;$window.Show();$window.Activate()|Out-Null;Wait-Ui 1800
$manual.Invoke($window,@())|Out-Null;$source.GraphX=48;$source.GraphY=48;$threshold.GraphX=456;$threshold.GraphY=96;$contour.GraphX=864;$contour.GraphY=48;$fit.GraphX=456;$fit.GraphY=420;$judge.GraphX=864;$judge.GraphY=420;foreach($tool in @($source,$threshold,$contour,$fit,$judge)){$tool.HasManualGraphPosition=$true}
