$main.GetField('RightTabs',$all).GetValue($window).SelectedItem=$main.GetField('DockConfigurationTab',$all).GetValue($window);$main.GetField('DockConfigurationTabs',$all).GetValue($window).SelectedIndex=0;$main.GetField('ImageContextComboBox',$all).GetValue($window).SelectedValue='ModuleInput';$main.GetField('FlowZoomSlider',$all).GetValue($window).Value=.45;$refresh.Invoke($window,@())|Out-Null;Wait-Ui 1000
$dock=$main.GetField('DockXldCircleFittingPanel',$all).GetValue($window);$history=$main.GetField('FlowEditHistoryText',$all).GetValue($window);$undoCount=$main.GetField('flowUndoHistory',$private).GetValue($window).Count;$radius=$null;if(-not $fit.TryGetOutputValue('Radius',[ref]$radius)){throw 'Radius output missing.'};$radiusError=[Math]::Abs(([double]$radius)-110.0);if($dock.Visibility.ToString() -ne 'Visible' -or $undoCount -ne 1 -or $radiusError -gt 2){throw "S23 visible state missing: dock=$($dock.Visibility), history=$($history.Text), radius=$radius"};$dock.BringIntoView();Wait-Ui 600
$size=Save-Shot $OutputPath;$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();Write-Output ('S23_UI_CAPTURE=PASS; Path={0}; Window={1}; A=UNDO_REDO_MENU_TOOLBAR/HISTORY_1_0/REAL_DTO_SNAPSHOT; B=XLD_CIRCLE_FIT_DOCK/ATUKEY/MAX_CLOSURE/CENTER_RADIUS_ANGLES_RESIDUAL; Graph=IMAGE_TO_REGION_TO_XLD_TO_CIRCLE_TO_RADIUS_JUDGE; Radius={2:0.###}; BSB=NOT_IMPLEMENTED_BY_USER_DIRECTIVE' -f $OutputPath,$size,[double]$radius)
